problems.solutionCode:
#include <stdio.h>

int main() {
    long long x, y;
    char op;
    if (scanf("%lld %c %lld", &x, &op, &y) != 3) return 0;
    switch (op) {
        case '+': printf("%lld\n", x + y); break;
        case '-': printf("%lld\n", x - y); break;
        case '*': printf("%lld\n", x * y); break;
        case '/':
            if (y == 0) {
                printf("ERROR\n");
            } else {
                printf("%lld\n", x / y);
            }
            break;
        default:
            printf("ERROR\n");
            break;
    }
    return 0;
}

