problems.solutionCode:
#include <stdio.h>
#include <stdbool.h>

#define MAX 200005
bool is_prime[MAX];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    if (n < 2) {
        printf("0\n");
        return 0;
    }
    for (int i = 2; i <= n; i++) is_prime[i] = true;
    for (int p = 2; p * p <= n; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i <= n; i += p)
                is_prime[i] = false;
        }
    }
    int count = 0;
    for (int i = 2; i <= n; i++) {
        if (is_prime[i]) count++;
    }
    printf("%d\n", count);
    return 0;
}

