#include <stdio.h>

unsigned long long factorial(int n) {
    if (n <= 1) return 1ULL;
    unsigned long long res = 1ULL;
    for (int i = 2; i <= n; i++) {
        res *= (unsigned long long)i;
    }
    return res;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    printf("%llu\n", factorial(n));
