#include <stdio.h>

void compute_sum_avg(const int *arr, int n, long long *sum_out, double *avg_out) {
    long long total = 0;
    for (int i = 0; i < n; i++) {
        total += arr[i];
    }
    *sum_out = total;
    *avg_out = (double)total / (double)n;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    static int arr[100005];
    for (int i = 0; i < n; i++) {
