problems.solutionCode:
#include <stdio.h>

void reverse_array(int *start, int *end) {
    while (start < end) {
        int temp = *start;
        *start = *end;
        *end = temp;
        start++;
        end--;
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    static int arr[100005];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &arr[i]) != 1) return 0;
    }
    reverse_array(&arr[0], &arr[n - 1]);
    for (int i = 0; i < n; i++) {
        printf("%d%c", arr[i], (i == n - 1 ? '\n' : ' '));
    }
    return 0;
}

