#include <stdio.h>

int str_len_ptr(const char *s) {
    const char *p = s;
    while (*p != '\0') {
        p++;
    }
    return (int)(p - s);
}

void str_rev_ptr(char *s) {
    int len = str_len_ptr(s);
    char *left = s;
    char *right = s + len - 1;
    while (left < right) {
        char temp = *left;
        *left = *right;
        *right = temp;
        left++;
        right--;
    }
}

int main() {
    static char str[100005];
    if (scanf("%s", str) != 1) return 0;
    printf("%d\n", str_len_ptr(str));
    str_rev_ptr(str);
    printf("%s\n", str);
    return 0;
}

