#include <stdio.h>

long long mod_pow(long long base, long long exp, long long mod) {
    if (mod == 1) return 0;
    if (exp == 0) return 1 % mod;
    base %= mod;
    long long half = mod_pow(base, exp / 2, mod);
    long long res = (half * half) % mod;
    if (exp % 2 == 1) {
        res = (res * base) % mod;
    }
    return res;
}

