int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    long long max_so_far = -2000000000000000000LL;
    long long current_sum = 0;
    for (int i = 0; i < n; i++) {
        long long x;
        if (scanf("%lld", &x) != 1) return 0;
        if (i == 0) {
            max_so_far = x;
            current_sum = x;
        } else {
            if (current_sum + x > x) {
                current_sum += x;
            } else {
                current_sum = x;
            }
            if (current_sum > max_so_far) {
                max_so_far = current_sum;
            }
        }
    }
    printf("%lld\n", max_so_far);
    return 0;
}

