problems.solutionCode:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    int capacity = 2;
    int size = 0;
    long long *data = (long long *)malloc((size_t)capacity * sizeof(long long));
    if (!data) return 0;

    char cmd[20];
    while (q--) {
        if (scanf("%s", cmd) != 1) break;
        if (strcmp(cmd, "PUSH") == 0) {
            long long val;
            if (scanf("%lld", &val) != 1) break;
            if (size == capacity) {
                capacity *= 2;
                data = (long long *)realloc(data, (size_t)capacity * sizeof(long long));
            }
            data[size++] = val;
        } else if (strcmp(cmd, "POP") == 0) {
            if (size > 0) {
                size--;
            } else {
                printf("EMPTY\n");
            }
        } else if (strcmp(cmd, "GET") == 0) {
            int idx;
            if (scanf("%d", &idx) != 1) break;
            if (idx >= 0 && idx < size) {
                printf("%lld\n", data[idx]);
            } else {
                printf("OUT_OF_BOUNDS\n");
            }
        } else if (strcmp(cmd, "SIZE") == 0) {
            printf("%d %d\n", size, capacity);
        }
    }

    free(data);
    return 0;
}

