problems.solutionCode:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node {
    long long data;
    struct Node *next;
};

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    struct Node *head = NULL;
    struct Node *tail = NULL;

    char cmd[30];
    while (q--) {
        if (scanf("%s", cmd) != 1) break;
        if (strcmp(cmd, "INSERT_HEAD") == 0) {
            long long val;
            if (scanf("%lld", &val) != 1) break;
            struct Node *node = (struct Node *)malloc(sizeof(struct Node));
            node->data = val;
            node->next = head;
            head = node;
            if (!tail) tail = node;
        } else if (strcmp(cmd, "INSERT_TAIL") == 0) {
            long long val;
            if (scanf("%lld", &val) != 1) break;
            struct Node *node = (struct Node *)malloc(sizeof(struct Node));
            node->data = val;
            node->next = NULL;
            if (tail) {
                tail->next = node;
                tail = node;
            } else {
                head = tail = node;
            }
        } else if (strcmp(cmd, "DELETE_HEAD") == 0) {
            if (!head) {
                printf("EMPTY\n");
            } else {
                struct Node *temp = head;
                head = head->next;
                if (!head) tail = NULL;
                free(temp);
            }
        } else if (strcmp(cmd, "PRINT") == 0) {
            if (!head) {
                printf("EMPTY\n");
            } else {
                struct Node *curr = head;
                while (curr) {
                    printf("%lld%c", curr->data, (curr->next ? ' ' : '\n'));
                    curr = curr->next;
                }
            }
        }
    }

    // Clean up
    while (head) {
        struct Node *temp = head;
        head = head->next;
        free(temp);
    }
    return 0;
}

